function BambooPlayer:Awake()
end

function BambooPlayer:Start()
end

function BambooPlayer:Initialize()
    self.processor = self.controller.gameObject:GetComponentInChildren(typeof(ChapterProcessor))
    self.markers = self.processor:GetAllWaitTLFinishMarkers()

    self.tlUICamera = self.controller.transform:Find("UICameraTop").gameObject:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
    --self:InitStack()
    
    if self.useCustomTouchHandler == true then
        return
    end

    self.touch = GameObject()
    self.touch.transform:SetParent(self.tlUICamera.transform:GetChild(0):Find("ChapterNewUI"))
    KTool.ResetTransform(self.touch.transform)
    self.touch.transform.localScale = Vector3(50, 50, 1)
    self.touch.name = "TouchHandler"
    self.touch.layer = 15
    self.touch:EnsureComponent(typeof(CS.UnityEngine.CanvasRenderer))
    self.touch = self.touch:EnsureComponent(typeof(CS.Engine.UI.GraphicRaycastReceiver))
    KTool.SetActive(self.touch, false)
    self.touch.transform:SetAsLastSibling()
    local proxy = UIEventProxy.Create(self.touch.gameObject)
    proxy.onPointerClick = function()
        self.waitForBreak = false
        KTool.SetActive(self.touch, false)
    end
end

--- 设置自定义的点击UI
---@param touchRootGO any
---@param touchClickGO any
function BambooPlayer:SetCustomTouchHandler(touchRootGO, touchClickGO)
    self.useCustomTouchHandler = true
    self.touchRootGO = touchRootGO
    local proxy = UIEventProxy.Create(touchClickGO)
    proxy.onPointerClick = function()
        self.waitForBreak = false
        KTool.SetActive(self.touchRootGO, false)
    end
end

function BambooPlayer:StartPlay()
    self.waitCo = cs_coroutine.start(function()

        printInfo("BambooPlayer start")
        local director = nil
        local pre = nil
        if isNull(self.markers) then
            return
        end

        for i = 1, self.markers.Count do
            director = self.markers[i - 1].Director:Resolve(self.processor.DirectorControl)
            if not isNull(director) then
                KTool.SetActive(director.gameObject, true)
                

                if not isNull(pre) then
                    KTool.SetActive(pre, false)
                end

                pre = director
                director:Play()

                if not isNull(self.processor.OnSingleChapterStart) then
                    self.processor.OnSingleChapterStart(director)
                end

                if director.extrapolationMode == CS.UnityEngine.Playables.DirectorWrapMode.Loop then

                    self.waitForBreak = true
                    if self.useCustomTouchHandler then
                        KTool.SetActive(self.touchRootGO, true)
                    else
                        KTool.SetActive(self.touch, true)
                    end
                    
                    while self.waitForBreak do
                        coroutine.yield()
                    end
                    
                else
                    coroutine.yield(WaitForTimelineFinish(director))
                end
                

                if not isNull(self.processor.OnSingleChapterFinish) then
                    self.processor.OnSingleChapterFinish(director)
                end
                --if director.gameObject.name == "" then
                --    KTool.SetActive(self.model, false)
                --end
            end
        end

        if not isNull(self.processor.OnChapterFinish) then
            self.processor.OnChapterFinish()
        end
        

        printInfo("BambooPlayer end")
    end)

    return self.waitCo
end

function BambooPlayer:OnDestroy()
    if self.waitCo ~= nil then
        cs_coroutine.stop(self.waitCo)
        self.waitCo = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return BambooPlayer